    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Vet> findVets() throws DataAccessException {
        return vetRepository.findAll();
    }

    /**
     * The number of owners, counted from the very first one ever created, that receive the
     * {@code FOUNDING} membership tier. Every owner created after this threshold is {@code STANDARD}.
     */
    private static final int MAX_FOUNDING_OWNERS = 100;

    @Override
    @Transactional
    public void saveOwner(Owner owner) throws DataAccessException {
        if (owner.isNew()) {
            if (owner.getRegistrationDate() == null) {
                owner.setRegistrationDate(LocalDate.now());
            }
            if (isDailyRegistrationLimitReached(owner)) {
                throw new OwnerRegistrationLimitException(
                    "The maximum number of owners that can be registered today has been reached");
            }
            if (isCityCapacityReached(owner)) {
                throw new OwnerCityCapacityException(
                    "The maximum number of owners that can be registered in this city has been reached");
            }
            owner.setCity(resolveCity(owner));
            owner.setMembershipNumber(ownerRepository.findAll().size() + 1);
            owner.setMembershipTier(owner.getMembershipNumber() <= MAX_FOUNDING_OWNERS ? "FOUNDING" : "STANDARD");
            owner.setCustomerCode(generateCustomerCode(owner));
            owner.setNamesakeCount(countNamesakes(owner));
            if (isDuplicateTelephone(owner)) {
                throw new DuplicateOwnerException(
                    "An owner with the same telephone already exists");
            }
            if (isDuplicateEmail(owner)) {
                throw new DuplicateOwnerException(
                    "An owner with the same email already exists");
            }
        }
        ownerRepository.save(owner);

    }

    /**
     * Count how many other owners already share this owner's last name at the
     * moment of creation (compared case-insensitively). The owner being created
     * is not yet persisted and is therefore never included in the count.
     */
    private int countNamesakes(Owner owner) {
        String lastName = owner.getLastName();
        if (lastName == null) {
            return 0;
        }
        return (int) ownerRepository.findAll().stream()
            .filter(existing -> !existing.getId().equals(owner.getId()))
            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
            .count();
    }

    /**
     * Build a customer code for a newly created owner, formatted as
     * {@code <UPPERCASE_CITY>-<NNNN>} where NNNN is one more than the number of
     * owners already registered in that city, zero-padded to four digits
     * (e.g. {@code LONDON-0007}).
     */
    private String generateCustomerCode(Owner owner) {
        String city = owner.getCity();
        long existingInCity = ownerRepository.findAll().stream()
            .filter(existing -> !existing.getId().equals(owner.getId()))
            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
            .count();
        String prefix = city == null ? "" : city.toUpperCase(Locale.ROOT);
        return String.format("%s-%04d", prefix, existingInCity + 1);
    }

    /**
     * Determine the city to store for a newly created owner. If another owner is
     * already registered in the same city (compared case-insensitively), reuse
     * that owner's exact spelling of the city name so the whole clinic agrees on
     * one canonical form. Otherwise the supplied city is title-cased (each
     * whitespace-separated word capitalised, e.g. "new york" becomes
     * "New York"). A {@code null} city stays {@code null}.
     */
    private String resolveCity(Owner owner) {
        String city = owner.getCity();
        if (city == null) {
            return null;
        }
        return ownerRepository.findAll().stream()
            .filter(existing -> !existing.getId().equals(owner.getId()))
            .map(Owner::getCity)
            .filter(existingCity -> existingCity != null && existingCity.equalsIgnoreCase(city))
            .findFirst()
            .orElseGet(() -> toTitleCase(city));
    }

    /**
     * Title-case a value by upper-casing the first letter of every
     * whitespace-separated word and lower-casing the remaining letters, while
     * preserving the original whitespace. A {@code null} value stays
     * {@code null}.
     */
    private static String toTitleCase(String value) {
        if (value == null) {
            return null;
        }
        StringBuilder result = new StringBuilder(value.length());
        boolean startOfWord = true;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (Character.isWhitespace(c)) {
                startOfWord = true;
                result.append(c);
            } else if (startOfWord) {
                result.append(Character.toTitleCase(Character.toLowerCase(c)));
                startOfWord = false;
            } else {
                result.append(Character.toLowerCase(c));
            }
        }
        return result.toString();
    }

    /**
     * The maximum number of owners that may be registered on any single day (by registration date).
     */
    private static final int MAX_OWNERS_PER_DAY = 20;

    /**
     * Determine whether the daily registration limit has already been reached for the day the given
     * owner is being registered on. Counts the existing owners whose registration date matches the new
     * owner's registration date and returns {@code true} once that count has reached
     * {@link #MAX_OWNERS_PER_DAY}.
     */
    private boolean isDailyRegistrationLimitReached(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return false;
        }
        long registeredToday = ownerRepository.findAll().stream()
            .filter(existing -> !existing.getId().equals(owner.getId()))
            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
            .count();
